/**
 * Site-wide Open Graph constants for duyet.net.
 *
 * One card for the whole site: `public/og.png`, generated by
 * `pnpm run og:card` (scripts/generate-og.ts) and committed so the URL that the
 * prerendered HTML references resolves on the CDN the moment a deploy lands.
 *
 * Every route re-emits the card through `ogMeta()` rather than leaning on the
 * root route's tags. TanStack Start dedupes `meta[]` by `name`/`property` with
 * the leaf route winning, so a route that overrides `og:url` / `og:title`
 * without re-declaring the image would silently keep the root card's alt text
 * and dimensions attached to a different page title.
 */

export const SITE_URL = "https://duyet.net";

export const SITE_TITLE = "Duyet — building AI agents and data platforms";

export const SITE_DESCRIPTION =
  "I build AI agents and the data platforms that keep them honest — end-to-end, obsessing over the small details that make software feel right to use.";

export const SITE_OG_IMAGE = `${SITE_URL}/og.png`;

/** One image across the site, so one alt text describes it on every page. */
export const SITE_OG_IMAGE_ALT =
  "Duyet.net — building AI agents and data platforms";
